  7	const funderIdPattern =
  8	  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
  9	const memberIdPattern = /^[1-9]\d*$/u;
 10	
 11	export function readDetailRoute(path: string): DetailRoute {
 12	  if (path === "/") return { kind: "search" };
 13	  const member = /^\/members\/([^/]+)\/?$/u.exec(path);
 14	  if (
 15	    member &&
 16	    memberIdPattern.test(member[1]) &&
 17	    Number(member[1]) <= 2147483647
 18	  )
 19	    return { kind: "member", id: member[1] };
 20	  const funder = /^\/funders\/([^/]+)\/?$/u.exec(path);
 21	  if (funder && funderIdPattern.test(funder[1]))
 22	    return { kind: "funder", id: funder[1] };
 23	  return { kind: "invalid" };
 24	}
