 41	export interface MemberDetails {
 42	  member: MemberProfile;
 43	  declarations: {
 44	    sourceId: number;
 45	    categoryName: string;
 46	    registeredAt: string | null;
 47	    entries: FundingEntry[];
 48	  }[];
 49	  declarationCount: number;
 50	  declarationLimit: number;
 51	}
 52	
 53	interface Total {
 54	  amount: string | null;
 55	  entryCount: number;
 56	  unknownAmountCount: number;
 57	}
 58	
 59	export interface FunderDetails {
 60	  funder: {
 61	    id: string;
 62	    name: string;
 63	    funderKind: string | null;
 64	    companyNumber: string | null;
 65	    aliases: string[];
 66	  };
 67	  currencies: {
 68	    currency: string;
 69	    parties: (Total & { partyName: string })[];
 70	    topRecipients: (Total & { member: MemberProfile })[];
 71	  }[];
 72	  entryCount: number;
 73	  unknownCurrencyCount: number;
 74	  recipientLimit: number;
 75	}
