 77	export type DetailState =
 78	  | { kind: "loading" }
 79	  | { kind: "member"; details: MemberDetails }
 80	  | { kind: "funder"; details: FunderDetails }
 81	  | { kind: "not-found" }
 82	  | { kind: "error"; message: string };
 83	
 84	function malformed(): never {
 85	  throw new Error("Details returned an unexpected response. Try again.");
 86	}
 87	function isRecord(value: unknown): value is Record<string, unknown> {
 88	  return typeof value === "object" && value !== null && !Array.isArray(value);
 89	}
 90	function record(value: unknown): Record<string, unknown> {
 91	  return isRecord(value) ? value : malformed();
 92	}
 93	function text(value: unknown): string {
 94	  return typeof value === "string" ? value : malformed();
 95	}
 96	function nullableText(value: unknown): string | null {
 97	  return value === null ? null : text(value);
 98	}
 99	function count(value: unknown): number {
100	  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
101	    ? value
102	    : malformed();
103	}
104	function list(value: unknown): unknown[] {
105	  return Array.isArray(value) ? value : malformed();
106	}
107	function decimal(value: unknown): string | null {
108	  const result = nullableText(value);
109	  if (result !== null && !/^-?\d+(?:\.\d+)?$/u.test(result)) return malformed();
110	  return result;
111	}
112	function identity(value: unknown, kind: "MP" | "Funder"): string {
113	  const id = text(value);
114	  if (
115	    kind === "MP"
116	      ? !memberIdPattern.test(id) || Number(id) > 2147483647
117	      : !funderIdPattern.test(id)
118	  )
119	    return malformed();
120	  return id;
121	}
122	function memberProfile(value: unknown): MemberProfile {
123	  const row = record(value);
124	  if (typeof row.is_current_commons !== "boolean") return malformed();
125	  return {
126	    id: identity(row.id, "MP"),
127	    name: text(row.name),
128	    partyName: text(row.party_name),
129	    membershipFrom: text(row.membership_from),
130	    isCurrentCommons: row.is_current_commons,
131	  };
132	}
133	function readMember(value: unknown): MemberDetails {
134	  const row = record(value);
135	  return {
136	    member: memberProfile(row.member),
137	    declarationCount: count(row.declaration_count),
138	    declarationLimit: count(row.declaration_limit),
139	    declarations: list(row.declarations).map((value) => {
140	      const declaration = record(value);
141	      const registeredAt = nullableText(declaration.registered_at);
142	      if (registeredAt !== null && !Number.isFinite(Date.parse(registeredAt)))
143	        return malformed();
144	      return {
145	        sourceId: count(declaration.source_id),
146	        categoryName: text(declaration.category_name),
147	        registeredAt,
148	        entries: list(declaration.entries).map((value) => {
149	          const entry = record(value);
150	          const funder = entry.funder === null ? null : record(entry.funder);
151	          return {
152	            funder:
153	              funder === null
154	                ? null
155	                : {
156	                    id: identity(funder.id, "Funder"),
157	                    name: text(funder.name),
158	                  },
159	            amount: decimal(entry.amount),
160	            currency: nullableText(entry.currency),
161	            paymentType: nullableText(entry.payment_type),
162	          };
163	        }),
164	      };
165	    }),
166	  };
167	}
168	function total(row: Record<string, unknown>): Total {
169	  return {
170	    amount: decimal(row.amount),
171	    entryCount: count(row.entry_count),
172	    unknownAmountCount: count(row.unknown_amount_count),
173	  };
174	}
175	function readFunder(value: unknown): FunderDetails {
176	  const row = record(value);
177	  const funder = record(row.funder);
178	  return {
179	    funder: {
180	      id: identity(funder.id, "Funder"),
181	      name: text(funder.name),
182	      funderKind: nullableText(funder.funder_kind),
183	      companyNumber: nullableText(funder.company_number),
184	      aliases: list(funder.aliases).map(text),
185	    },
186	    entryCount: count(row.entry_count),
187	    unknownCurrencyCount: count(row.unknown_currency_count),
188	    recipientLimit: count(row.recipient_limit),
189	    currencies: list(row.currencies).map((value) => {
190	      const group = record(value);
191	      const currency = text(group.currency);
192	      if (!currency.trim()) return malformed();
193	      return {
194	        currency,
195	        parties: list(group.parties).map((value) => {
196	          const party = record(value);
197	          return { ...total(party), partyName: text(party.party_name) };
198	        }),
199	        topRecipients: list(group.top_recipients).map((value) => {
200	          const recipient = record(value);
201	          return {
202	            ...total(recipient),
203	            member: memberProfile(recipient.member),
204	          };
205	        }),
206	      };
207	    }),
208	  };
209	}
