211	export async function loadDetails(
212	  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
213	  signal: AbortSignal,
214	): Promise<DetailState> {
215	  const controller = new AbortController();
216	  const cancel = () => controller.abort();
217	  signal.addEventListener("abort", cancel, { once: true });
218	  if (signal.aborted) cancel();
219	  let timedOut = false;
220	  const timer = setTimeout(() => {
221	    timedOut = true;
222	    controller.abort();
223	  }, 10_000);
224	  try {
225	    const response = await fetch(
226	      `/api/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
227	      { signal: controller.signal },
228	    );
229	    if (response.status === 404) return { kind: "not-found" };
230	    if (!response.ok)
231	      throw new Error(
232	        "The details service is unavailable. Try again in a moment.",
233	      );
234	    const body: unknown = await response.json();
235	    const state: DetailState =
236	      route.kind === "member"
237	        ? { kind: "member", details: readMember(body) }
238	        : { kind: "funder", details: readFunder(body) };
239	    if (
240	      (state.kind === "member"
241	        ? state.details.member.id
242	        : state.details.funder.id
243	      ).toLowerCase() !== route.id.toLowerCase()
244	    )
245	      return malformed();
246	    return state;
247	  } catch (error) {
248	    if (signal.aborted) throw error;
249	    return {
250	      kind: "error",
251	      message: timedOut
252	        ? "Details are taking too long. Try again."
253	        : error instanceof Error &&
254	            !(error instanceof TypeError || error instanceof SyntaxError)
255	          ? error.message
256	          : "Couldn’t connect to details. Check your connection and try again.",
257	    };
258	  } finally {
259	    clearTimeout(timer);
260	    signal.removeEventListener("abort", cancel);
261	  }
262	}
263	
264	export function backToSearch(): string {
265	  const params = new URLSearchParams(window.location.search);
266	  const retained = new URLSearchParams();
267	  for (const key of ["q", "strictness"]) {
268	    const value = params.get(key);
269	    if (value !== null) retained.set(key, value);
270	  }
271	  return retained.size ? `/?${retained}` : "/";
272	}
273	
274	export function formatAmount(value: string | null): string {
275	  if (value === null) return "Amount unavailable";
276	  const negative = value.startsWith("-");
277	  const unsigned = negative ? value.slice(1) : value;
278	  const [whole, fraction] = unsigned.split(".");
279	  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
280	}
281	
282	export function registrationDate(value: string): string {
283	  return new Intl.DateTimeFormat("en-GB", {
284	    day: "numeric",
285	    month: "short",
286	    year: "numeric",
287	    timeZone: "UTC",
288	  }).format(new Date(value));
289	}

