    55	  entryCount: number;
    56	  unknownAmountCount: number;
    57	}
    58	
    59	export interface FunderDetails {
    60	  funder: {
    61	    id: string;
    62	    name: string;
    63	    funderKind: string | null;
    64	    companyNumber: string | null;
    65	    aliases: string[];
    66	  };
    67	  currencies: {
    68	    currency: string;
    69	    parties: (Total & { partyName: string })[];
    70	    topRecipients: (Total & { member: MemberProfile })[];
    71	  }[];
    72	  entryCount: number;
    73	  unknownCurrencyCount: number;
    74	  recipientLimit: number;
    75	}
