    83	
    84	function malformed(): never {
    85	  throw new Error("Details returned an unexpected response. Try again.");
    86	}
    87	function isRecord(value: unknown): value is Record<string, unknown> {
    88	  return typeof value === "object" && value !== null && !Array.isArray(value);
    89	}
    90	function record(value: unknown): Record<string, unknown> {
    91	  return isRecord(value) ? value : malformed();
    92	}
    93	function text(value: unknown): string {
    94	  return typeof value === "string" ? value : malformed();
    95	}
    96	function nullableText(value: unknown): string | null {
    97	  return value === null ? null : text(value);
    98	}
    99	function count(value: unknown): number {
   100	  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
