   205	        }),
   206	      };
   207	    }),
   208	  };
   209	}
   210	
   211	export async function loadDetails(
   212	  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
   213	  signal: AbortSignal,
   214	): Promise<DetailState> {
   215	  const controller = new AbortController();
   216	  const cancel = () => controller.abort();
   217	  signal.addEventListener("abort", cancel, { once: true });
   218	  if (signal.aborted) cancel();
   219	  let timedOut = false;
   220	  const timer = setTimeout(() => {
   221	    timedOut = true;
   222	    controller.abort();
   223	  }, 10_000);
   224	  try {
   225	    const response = await fetch(
   226	      `/api/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
   227	      { signal: controller.signal },
   228	    );
   229	    if (response.status === 404) return { kind: "not-found" };
   230	    if (!response.ok)
   231	      throw new Error(
   232	        "The details service is unavailable. Try again in a moment.",
   233	      );
   234	    const body: unknown = await response.json();
   235	    const state: DetailState =
   236	      route.kind === "member"
   237	        ? { kind: "member", details: readMember(body) }
   238	        : { kind: "funder", details: readFunder(body) };
