   260	    signal.removeEventListener("abort", cancel);
   261	  }
   262	}
   263	
   264	export function backToSearch(): string {
   265	  const params = new URLSearchParams(window.location.search);
   266	  const retained = new URLSearchParams();
   267	  for (const key of ["q", "strictness"]) {
   268	    const value = params.get(key);
   269	    if (value !== null) retained.set(key, value);
   270	  }
   271	  return retained.size ? `/?${retained}` : "/";
   272	}
   273	
   274	export function formatAmount(value: string | null): string {
