   276	  const negative = value.startsWith("-");
   277	  const unsigned = negative ? value.slice(1) : value;
   278	  const [whole, fraction] = unsigned.split(".");
   279	  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
   280	}
   281	
   282	export function registrationDate(value: string): string {
   283	  return new Intl.DateTimeFormat("en-GB", {
   284	    day: "numeric",
   285	    month: "short",
   286	    year: "numeric",
   287	    timeZone: "UTC",
   288	  }).format(new Date(value));
   289	}
