 94	      )
 95	        throw new Error(
 96	          "Search returned an unexpected MP identity. Try again.",
 97	        );
 98	      return {
 99	        id: value.id,
100	        name: value.name,
101	        kind: "MP",
102	        funderKind: null,
103	        matchSource,
104	      };
105	    }
106	    if (
107	      !/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu.test(
108	        value.id,
109	      )
110	    )
111	      throw new Error(
112	        "Search returned an unexpected funder identity. Try again.",
113	      );
114	    return {
115	      id: value.id,
116	      name: value.name,
117	      kind: "Funder",
118	      funderKind: value.funder_kind,
119	      matchSource,
120	    };
121	  });
