124	export async function searchEntities(
125	  term: string,
126	  signal: AbortSignal,
127	  strictness: number,
128	): Promise<Entity[]> {
129	  const controller = new AbortController();
130	  let timedOut = false;
131	  const cancel = () => controller.abort();
132	  signal.addEventListener("abort", cancel, { once: true });
133	  if (signal.aborted) cancel();
134	  const timeout = setTimeout(() => {
135	    timedOut = true;
136	    controller.abort();
137	  }, searchConfiguration.timeoutMs);
138	
139	  try {
140	    const params = new URLSearchParams({
141	      term,
142	      max_entries: String(searchConfiguration.maxEntriesPerType),
143	      strictness: String(strictness),
144	    });
145	    const response = await fetch(`/api/search?${params}`, {
146	      signal: controller.signal,
147	    });
148	    if (!response.ok) {
149	      throw new Error(
150	        "The search service is unavailable. Try again in a moment.",
151	      );
152	    }
153	    const body: unknown = await response.json();
154	    return readEntities(body);
155	  } catch (error) {
156	    if (timedOut) throw new Error("Search is taking too long. Try again.");
157	    if (signal.aborted) throw error;
158	    if (error instanceof TypeError || error instanceof SyntaxError) {
159	      throw new Error(
160	        "Couldn’t connect to search. Check your connection and try again.",
161	      );
162	    }
163	    throw error;
164	  } finally {
165	    clearTimeout(timeout);
166	    signal.removeEventListener("abort", cancel);
167	  }
168	}
