175	export function funderKindLabel(value: string | null): string {
176	  const kind = value?.trim();
177	  if (!kind || kind.toLowerCase() === "not specified") return "Unclassified";
178	  if (kind.toLowerCase() === "individual") return "Individual";
179	  if (kind.toLowerCase() === "company") return "Company";
180	  if (kind.toLowerCase() === "trade union") return "Trade union";
181	  return kind;
182	}
