199	// Plain-text segments keep source names intact and never interpret names or
200	// user input as markup. Matching here only highlights; it never changes rank.
201	export function highlightName(name: string, term: string) {
202	  const tokens = [...new Set(term.trim().split(/\s+/u).filter(Boolean))]
203	    .sort((a, b) => b.length - a.length)
204	    .map((token) => token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
205	  if (!tokens.length) return [{ text: name, matched: false }];
206	  const pattern = new RegExp(tokens.join("|"), "giu");
207	  const segments: { text: string; matched: boolean }[] = [];
208	  let position = 0;
209	  for (const match of name.matchAll(pattern)) {
210	    const start = match.index;
211	    if (start > position)
212	      segments.push({ text: name.slice(position, start), matched: false });
213	    segments.push({ text: match[0], matched: true });
214	    position = start + match[0].length;
215	  }
216	  if (position < name.length)
217	    segments.push({ text: name.slice(position), matched: false });
218	  return segments;
219	}
