    11	export function readStrictness(value: string | null): number {
    12	  if (!value?.trim()) return searchConfiguration.strictness;
    13	  const parsed = Number(value);
    14	  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1
    15	    ? Math.round(parsed * 100) / 100
    16	    : searchConfiguration.strictness;
    17	}
