    19	export type SearchMatchSource =
    20	  { kind: "name" } | { kind: "alias"; name: string };
    21	
    22	export type Entity =
    23	  | {
    24	      id: string;
    25	      name: string;
    26	      kind: "MP";
    27	      funderKind: null;
    28	      matchSource: { kind: "name" };
    29	    }
    30	  | {
    31	      id: string;
    32	      name: string;
    33	      kind: "Funder";
    34	      funderKind: string | null;
    35	      matchSource: SearchMatchSource;
    36	    };
    37	
    38	export function entityHref(entity: Pick<Entity, "kind" | "id">): string {
    39	  const params = new URLSearchParams(window.location.search);
    40	  const retained = new URLSearchParams();
    41	  for (const key of ["q", "strictness"]) {
    42	    const value = params.get(key);
    43	    if (value !== null) retained.set(key, value);
    44	  }
    45	  const query = retained.size ? `?${retained}` : "";
    46	  return `/${entity.kind === "MP" ? "members" : "funders"}/${encodeURIComponent(entity.id)}${query}`;
    47	}
    48	
    49	function isRecord(value: unknown): value is Record<string, unknown> {
    50	  return typeof value === "object" && value !== null;
    51	}
    52	
    53	function readEntities(body: unknown): Entity[] {
    54	  if (!isRecord(body) || !Array.isArray(body.entities)) {
    55	    throw new Error("Search returned an unexpected response. Try again.");
    56	  }
    57	
    58	  return body.entities.map((value: unknown) => {
    59	    if (
    60	      !isRecord(value) ||
    61	      typeof value.name !== "string" ||
    62	      typeof value.id !== "string" ||
    63	      (value.kind !== "MP" && value.kind !== "Funder") ||
    64	      (value.funder_kind !== null && typeof value.funder_kind !== "string")
    65	    ) {
    66	      throw new Error("Search returned an unexpected response. Try again.");
    67	    }
    68	    const source = value.match_source;
    69	    if (!isRecord(source))
    70	      throw new Error("Search returned an unexpected match source. Try again.");
    71	    let matchSource: SearchMatchSource;
    72	    switch (source.kind) {
    73	      case "name":
    74	        matchSource = { kind: "name" };
    75	        break;
    76	      case "alias":
    77	        if (typeof source.name !== "string" || !source.name.trim())
    78	          throw new Error(
    79	            "Search returned an unexpected match source. Try again.",
    80	          );
    81	        matchSource = { kind: "alias", name: source.name };
    82	        break;
    83	      default:
    84	        throw new Error(
    85	          "Search returned an unexpected match source. Try again.",
    86	        );
    87	    }
    88	    if (value.kind === "MP") {
    89	      if (
    90	        !/^[1-9]\d*$/u.test(value.id) ||
    91	        Number(value.id) > 2147483647 ||
    92	        value.funder_kind !== null ||
    93	        matchSource.kind !== "name"
    94	      )
    95	        throw new Error(
    96	          "Search returned an unexpected MP identity. Try again.",
    97	        );
    98	      return {
    99	        id: value.id,
   100	        name: value.name,
   101	        kind: "MP",
   102	        funderKind: null,
   103	        matchSource,
   104	      };
   105	    }
   106	    if (
   107	      !/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu.test(
   108	        value.id,
   109	      )
   110	    )
   111	      throw new Error(
   112	        "Search returned an unexpected funder identity. Try again.",
   113	      );
   114	    return {
   115	      id: value.id,
   116	      name: value.name,
   117	      kind: "Funder",
   118	      funderKind: value.funder_kind,
   119	      matchSource,
   120	    };
   121	  });
   122	}
